#include "aethon/crypto/crypto.hpp"
#include "aethon/codec/crc.hpp"
#include "aethon/common/error.hpp"
namespace aethon::crypto { namespace {
class PlainCipher final : public Cipher { public: protocol::EncryptionMode mode() const noexcept override { return protocol::EncryptionMode::none; } Bytes seal(std::span<const std::uint8_t> input, const KeyMaterial&) const override { return {input.begin(), input.end()}; } Bytes open(std::span<const std::uint8_t> input, const KeyMaterial&) const override { return {input.begin(), input.end()}; } };
class EnvelopeCipher final : public Cipher { public: protocol::EncryptionMode mode() const noexcept override { return protocol::EncryptionMode::envelope; } Bytes seal(std::span<const std::uint8_t> plain, const KeyMaterial& key) const override { if (key.bytes.empty()) throw Error(ErrorCode::invalid_argument, "missing key material"); Bytes out; auto tag = codec::crc32c(key.bytes) ^ codec::crc32c(plain); for (int i = 0; i < 4; ++i) out.push_back(static_cast<std::uint8_t>((tag >> (8 * i)) & 0xff)); for (std::size_t i = 0; i < plain.size(); ++i) out.push_back(static_cast<std::uint8_t>(plain[i] ^ key.bytes[(i + key.key_id) % key.bytes.size()])); return out; } Bytes open(std::span<const std::uint8_t> sealed, const KeyMaterial& key) const override { if (sealed.size() < 4 || key.bytes.empty()) throw Error(ErrorCode::malformed_packet, "bad envelope"); Bytes plain; for (std::size_t i = 4; i < sealed.size(); ++i) plain.push_back(static_cast<std::uint8_t>(sealed[i] ^ key.bytes[(i - 4 + key.key_id) % key.bytes.size()])); std::uint32_t tag = 0; for (int i = 0; i < 4; ++i) tag |= static_cast<std::uint32_t>(sealed[i]) << (8 * i); if (tag != (codec::crc32c(key.bytes) ^ codec::crc32c(plain))) throw Error(ErrorCode::checksum_mismatch, "envelope tag mismatch"); return plain; } };
} std::unique_ptr<Cipher> make_cipher(protocol::EncryptionMode mode) { if (mode == protocol::EncryptionMode::none) return std::make_unique<PlainCipher>(); if (mode == protocol::EncryptionMode::envelope) return std::make_unique<EnvelopeCipher>(); throw Error(ErrorCode::invalid_argument, "unsupported encryption mode"); } }
